"""
AI Generation Data Transfer Schemas.
Contract between AI Gateway / AI Workspace (Dev 5) and Quiz Storage (Dev 2).
"""

from typing import List, Dict, Any, Optional
from pydantic import BaseModel, Field


class GeneratedQuestionSchema(BaseModel):
    """Schema for individual question generated by AI."""
    type: str = Field(..., description="Question type identifier (e.g. single_choice, multiple_choice, true_false)")
    prompt: str = Field(..., description="The main text / question prompt")
    options: List[Dict[str, Any]] = Field(default_factory=list, description="List of possible answer options")
    correct_answer: Any = Field(..., description="The correct answer key/value")
    explanation: Optional[str] = Field(None, description="Pedagogical explanation of the correct answer")
    difficulty: str = Field(default="medium", description="Difficulty level: easy, medium, hard")
    points: int = Field(default=1000, description="Point value for correct answer")
    time_limit_seconds: int = Field(default=30, description="Suggested time limit in seconds")


class GeneratedQuizPayload(BaseModel):
    """Schema for complete quiz payload generated by AI."""
    title: str = Field(..., description="Title of the quiz")
    subject: str = Field(..., description="Subject or topic of the quiz")
    grade_level: int = Field(default=7, description="Target school grade level (1-11)")
    locale: str = Field(default="uz-Latn", description="Language/locale of the quiz")
    questions: List[GeneratedQuestionSchema] = Field(..., description="List of generated questions")
